public class ReleaseGate
{
    const decimal Target = 1.0m; // "100% uptime"

    // One failed request closes the gate
    public bool CanDeploy(long good, long valid) => good >= Target * valid;

    // (1 - 1.0) x anything = no room for a single error
    public decimal AllowedErrors(long valid) => (1 - Target) * valid;
}
// 3,000,000 requests, 1 failed:
// CanDeploy = False, AllowedErrors = 0.0

public record Slo(decimal Target, int WindowDays); // e.g. 0.999 over 30 days

public static class ErrorBudget
{
    // Errors the SLO allows in the window: (1 - target) x valid events
    public static decimal Allowed(Slo slo, long valid) =>
        (1 - slo.Target) * valid;

    // Share of the budget left: 1 = untouched, 0 or less = spent
    public static decimal Remaining(Slo slo, long good, long valid) =>
        1 - (valid - good) / Allowed(slo, valid);

    // How fast errors spend it: 1 = the budget lasts exactly the window
    public static decimal BurnRate(Slo slo, long errors, long requests) =>
        (decimal)errors / requests / (1 - slo.Target);
}
// new Slo(0.999m, 30), 3,000,000 requests, 1,500 failed:
// Allowed = 3000.000, Remaining = 0.5
// Last hour, 144 failed of 10,000: BurnRate = 14.4
